import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';

const ModalContext = createContext(null);

export function Modal({ children, isOpen: controlledOpen, onClose }) {
  const [internalOpen, setInternalOpen] = useState(false);
  const isControlled = controlledOpen !== undefined;
  const isOpen = isControlled ? controlledOpen : internalOpen;

  const handleClose = () => {
    if (onClose) onClose();
    if (!isControlled) setInternalOpen(false);
  };

  return (
    <ModalContext.Provider value={{ isOpen, handleClose, openModal: () => setInternalOpen(true) }}>
      {children}
    </ModalContext.Provider>
  );
}

Modal.Trigger = function ModalTrigger({ children }) {
  const { openModal } = useContext(ModalContext);
  return React.cloneElement(children, { onClick: openModal });
};

Modal.Content = function ModalContent({ children, title }) {
  const { isOpen, handleClose } = useContext(ModalContext);
  const dialogRef = useRef(null);

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e) => {
      if (e.key === 'Escape') handleClose();
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  if (!isOpen) return null;

  return ReactDOM.createPortal(
    <div className='modal-backdrop' onClick={handleClose}>
      <div
        className='modal-card'
        role='dialog'
        aria-modal='true'
        ref={dialogRef}
        onClick={(e) => e.stopPropagation()}
      >
        {title && <h2>{title}</h2>}
        {children}
        <button onClick={handleClose} aria-label='Close'>×</button>
      </div>
    </div>,
    document.body
  );
};
```

