import { AsyncLocalStorage } from 'node:async_hooks';
import crypto from 'node:crypto';

export const tracer = new AsyncLocalStorage();

export function traceMiddleware(req, res, next) {
  const traceId = req.headers['x-trace-id'] || crypto.randomUUID();
  const store = {
    traceId,
    startTime: Date.now(),
    user: null
  };

  res.setHeader('X-Trace-Id', traceId);
  tracer.run(store, () => {
    next();
  });
}

// Usage anywhere in deep business logic or DB models:
export function logWithContext(message) {
  const store = tracer.getStore();
  const traceId = store ? store.traceId : 'no-trace';
  console.log(`[${new Date().toISOString()}] [${traceId}] ${message}`);
}
