const tokenBucketLua = `
  local key = KEYS[1]
  local capacity = tonumber(ARGV[1])
  local refillRate = tonumber(ARGV[2]) -- tokens per millisecond
  local now = tonumber(ARGV[3])
  local requested = tonumber(ARGV[4])

  local data = redis.call('HMGET', key, 'tokens', 'lastRefill')
  local tokens = tonumber(data[1])
  local lastRefill = tonumber(data[2])

  if not tokens then
    tokens = capacity
    lastRefill = now
  else
    local elapsed = now - lastRefill
    tokens = math.min(capacity, tokens + (elapsed * refillRate))
    lastRefill = now
  end

  if tokens >= requested then
    tokens = tokens - requested
    redis.call('HMSET', key, 'tokens', tokens, 'lastRefill', lastRefill)
    redis.call('PEXPIRE', key, 3600000) -- 1 hr TTL
    return { 1, math.floor(tokens) }
  else
    redis.call('HMSET', key, 'tokens', tokens, 'lastRefill', lastRefill)
    return { 0, math.floor(tokens) }
  end
`;

export const tokenBucketLimiter = (redisClient, capacity = 100, refillPerSec = 10) => {
  const refillRate = refillPerSec / 1000;
  return async (req, res, next) => {
    const key = `rate_limit:${req.ip}`;
    const now = Date.now();
    const [allowed, remaining] = await redisClient.eval(
      tokenBucketLua, 1, key, capacity, refillRate, now, 1
    );
    res.setHeader('X-RateLimit-Remaining', remaining);
    if (allowed === 1) return next();
    res.setHeader('Retry-After', Math.ceil(1 / refillPerSec));
    return res.status(429).json({ error: 'Too Many Requests (Token Bucket Exhausted)' });
  };
};
```

