import CircuitBreaker from 'opossum';

async function callPaymentGateway(paymentData) {
  const response = await fetch('https://api.payment-gateway.com/charge', {
    method: 'POST',
    body: JSON.stringify(paymentData),
    signal: AbortSignal.timeout(3000) // 3s network timeout
  });
  if (!response.ok) throw new Error(`Gateway Error: ${response.status}`);
  return response.json();
}

const options = {
  timeout: 3000, // Trigger failure if call takes > 3s
  errorThresholdPercentage: 50, // Open circuit if 50% fail
  resetTimeout: 15000 // Try again after 15s (Half-Open)
};

export const paymentBreaker = new CircuitBreaker(callPaymentGateway, options);

paymentBreaker.fallback(() => ({
  status: 'queued',
  message: 'Payment service currently experiencing high latency. Your request is queued for processing.'
}));

paymentBreaker.on('open', () => console.warn('⚠️ Circuit Breaker OPEN: Payment gateway offline!'));
paymentBreaker.on('halfOpen', () => console.log('⚡ Circuit Breaker HALF-OPEN: Testing gateway...'));
paymentBreaker.on('close', () => console.log('✅ Circuit Breaker CLOSED: Gateway healthy.'));
```

1. The Problem:
Consider creating an order:
```javascript
await db.orders.create(orderData);
await messageBroker.publish('order.created', orderData);
```
If the broker fails or network drops after the DB write, the event is lost forever (other microservices never know the order exists). If you reverse the order and publish first, a database rollback leaves an invalid ghost event in the broker.
2. Transactional Outbox Pattern:
Instead of calling the broker directly, write the event into an `outbox` table *within the exact same database transaction*:
```sql
BEGIN;
INSERT INTO orders (id, user_id, amount) VALUES ($1, $2, $3);
INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload) 
VALUES ('Order', $1, 'OrderCreated', $payload);
COMMIT;
```
Because both inserts happen in the same ACID transaction, both succeed or both fail atomically.
3. Relay Options:
- Change Data Capture (CDC with Debezium): Debezium tails the PostgreSQL Write-Ahead Log (WAL) or MongoDB Change Streams and automatically pushes outbox events to Kafka with zero polling overhead and at-least-once delivery guarantees.
- Polling Publisher: A background Node.js worker periodically queries `SELECT * FROM outbox_events WHERE processed = false FOR UPDATE SKIP LOCKED` and publishes to the broker, marking records processed.

1. Architecture Pattern:
Use the native browser `BroadcastChannel` API (or `window.dispatchEvent(new CustomEvent(...))` for single-window):
```javascript
// shared-events.js (Contract)
export const EVENT_BUS = new BroadcastChannel('app_enterprise_bus');

export const MicroEvents = {
  AUTH_CHANGE: 'AUTH_CHANGE',
  CART_UPDATE: 'CART_UPDATE'
};
```
2. Reusable React Hook:
```javascript
export function useMicroEvent(eventType, handler) {
  useEffect(() => {
    const onMessage = (event) => {
      if (event.data?.type === eventType) {
        handler(event.data.payload);
      }
    };
    EVENT_BUS.addEventListener('message', onMessage);
    return () => EVENT_BUS.removeEventListener('message', onMessage);
  }, [eventType, handler]);
}
```
3. Benefits: Zero bundle coupling. Each micro-frontend can be built with different React versions or deployed independently while maintaining instantaneous, tear-free event synchronization.

