import cluster from 'node:cluster';
import os from 'node:os';

if (cluster.isPrimary) {
  const numCPUs = os.cpus().length;
  console.log(`Primary ${process.pid} running. Spawning ${numCPUs} workers...`);

  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  // Rolling reload on SIGHUP
  process.on('SIGHUP', async () => {
    console.log('Received SIGHUP. Initiating rolling reload...');
    const workers = Object.values(cluster.workers);
    for (const worker of workers) {
      await new Promise((resolve) => {
        const newWorker = cluster.fork();
        newWorker.once('listening', () => {
          worker.disconnect();
          const timer = setTimeout(() => worker.kill(), 5000);
          worker.once('exit', () => {
            clearTimeout(timer);
            resolve();
          });
        });
      });
    }
    console.log('Rolling reload completed successfully.');
  });

  cluster.on('exit', (worker, code, signal) => {
    if (!worker.exitedAfterDisconnect) {
      console.warn(`Worker ${worker.process.pid} crashed (${signal || code}). Replacing...`);
      cluster.fork();
    }
  });
} else {
  import('./server.js'); // Worker application code
}
