import { MongoClient } from 'mongodb';
import Redis from 'ioredis';

const redis = new Redis();
const mongo = new MongoClient(process.env.MONGO_URI);

export async function startOrderStream() {
  await mongo.connect();
  const collection = mongo.db('commerce').collection('orders');

  const lastToken = await redis.get('mongo:stream:orders:resume_token');
  const options = lastToken ? { resumeAfter: JSON.parse(lastToken) } : {};

  const pipeline = [
    { $match: { operationType: 'update', 'updateDescription.updatedFields.status': 'completed' } }
  ];

  const stream = collection.watch(pipeline, options);
  console.log('⚡ Order Change Stream active with resume token recovery...');

  for await (const change of stream) {
    try {
      const orderId = change.documentKey._id;
      console.log(`Processing completed order: ${orderId}`);

      // Execute business logic (e.g. dispatch invoice email, trigger fulfillment)
      await processFulfillment(orderId);

      // Persist resume token only AFTER successful processing
      await redis.set('mongo:stream:orders:resume_token', JSON.stringify(change._id));
    } catch (err) {
      console.error('Error processing change event:', err);
      // Implement backoff or dead letter alert
    }
  }
}
