import crypto from 'node:crypto';

export function monitorThreadpool(intervalMs = 2000, thresholdMs = 40) {
  setInterval(() => {
    const start = performance.now();
    // Lightweight task dispatched to libuv threadpool
    crypto.pbkdf2('test', 'salt', 100, 16, 'sha512', (err) => {
      const duration = performance.now() - start;
      if (duration > thresholdMs) {
        console.warn(
          `🚨 [LIBUV THREADPOOL STARVATION] Duration: ${duration.toFixed(2)}ms (expected < 5ms). ` +
          `Thread pool is saturated! Current UV_THREADPOOL_SIZE=${process.env.UV_THREADPOOL_SIZE || 4}`
        );
      }
    });
  }, intervalMs).unref(); // unref so timer doesn't prevent clean shutdown
}
