import crypto from 'node:crypto';

export class DistributedLock {
  constructor(redisClient) {
    this.redis = redisClient;
  }

  async acquire(lockKey, ttlMs = 10000) {
    const lockId = crypto.randomUUID();
    const acquired = await this.redis.set(lockKey, lockId, 'PX', ttlMs, 'NX');
    if (!acquired) return null;

    // Start watchdog to renew lease while task executes
    const renewalInterval = setInterval(async () => {
      const luaRenew = `
        if redis.call('get', KEYS[1]) == ARGV[1] then
          return redis.call('pexpire', KEYS[1], ARGV[2])
        else
          return 0
        end
      `;
      await this.redis.eval(luaRenew, 1, lockKey, lockId, ttlMs);
    }, ttlMs / 3);

    const release = async () => {
      clearInterval(renewalInterval);
      const luaRelease = `
        if redis.call('get', KEYS[1]) == ARGV[1] then
          return redis.call('del', KEYS[1])
        else
          return 0
        end
      `;
      await this.redis.eval(luaRelease, 1, lockKey, lockId);
    };

    return { lockId, release };
  }
}
